"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["92727"],{146768(n){n.exports=JSON.parse('{"id":2356,"title":"111","description":"\u4ECE\u5B81\u57CE\u5F00\u5411\u676D\u57CE\u7684\u9AD8\u94C1\u4E0A\u3002\\n13\u5217\u8F662A\u4F4D\u7F6E\u4E0A\u7684\u8096\u5317\uFF0C\u6B64\u523B\u4E00\u8138\u7684\u832B\u7136\u3002\\n\u770B\u7740\u5468\u56F4\u7684\u73AF\u5883\uFF0C\u9677\u5165\u8FF7\u832B\u4E4B\u4E2D\u3002\\n\u6211\u662F\u8C01\uFF1F\\n\u6211\u5728\u54EA\u513F\uFF1F\\n\u6211\u4E0D\u662F\u6B63\u5728\u81EA\u5DF1\u7684\u529E\u516C\u5BA4\u548C\u81EA\u5DF1\u7684\u79D8\u4E66\u8BA8\u8BBA\u4EBA\u751F\u7684\u771F\u8C1B\u5417\uFF1F\\n\u6BD4\u5982\uFF1A\\n\u4E3A\u4EC0\u4E48\u4F60\u7684\u9ED1\u4E1D\u4E0A\u6709\u5B57\u6BCD\uFF1F\\n\u4E3A\u4EC0\u4E48\u4F60\u7684\u9AD8\u8DDF\u978B\u4E0A\u6709\u94C6\u9489\uFF1F\\n\u4E3A\u4EC0\u4E48\u8FD9\u4E48\u77ED\u7684\u88D9\u5B50\uFF0C\u5B83\u53EBJK\uFF1F\\n\u6700\u540E\u4E24\u4EBA\u5DF2\u7ECF\u4E0D\u6EE1\u8DB3\u8BA8\u8BBA\u4EBA\u751F\u7684\u771F\u8C1B\u4E86\uFF0C\u8FD8\u6253\u7B97\u5B9E\u8DF5\u4E00\u756A\u3002\\n\u4E8E\u662F\uFF0C\u8096\u5317\u548C\u5C0F\u79D8\u4E66\u679C\u65AD\u7684\u4E0A\u6765\u6218\u573A\uFF0C\u5927\u6218\u4E86\u4E09\u56DE\u5408\uFF01\\n\u4E00\u7741\u5F00\u773C\u775B\uFF0C\u5C0F\u79D8\u4E66\u6CA1\u6709\u4E86\uFF0C\u5B57\u6BCD\u9ED1\u4E1D\u4EC0\u4E48\u90FD\u6CA1\u6709\u4E86\u3002\\n\u8C6A\u534E\u529E\u516C\u5BA4\uFF0C\u53D8\u6210\u4E86\u5217\u8F66\u7684\u8F66\u53A2\u3002\u8F70~\uFF01\\n\u5C31\u5728\u8FD9\u4E2A\u65F6\u5019\uFF0C\u4E00\u80A1\u8BB0\u5FC6\u6D8C\u5165\u8096\u5317\u7684\u8111\u5B50\u4E4B\u4E2D\u3002\\n\u4E00\u5E55\u5E55\u8BB0\u5FC6\u7247\u6BB5\u5982\u540C\u5E7B\u706F\u7247\u4E00\u6837\uFF0C\u5728\u8096\u5317\u7684\u8111\u6D77\u4E2D\u95EA\u8FC7\u3002\\n\u534A\u664C\u540E\u3002\\n\u8096\u5317\u5FAE\u5FAE\u53F9\u4E86\u4E00\u53E3\u6C14\uFF0C\u65E0\u5948\u7684\u6447\u6447\u5934\u3002\\n\u901A\u8FC7\u8BB0\u5FC6\u7684\u4E86\u89E3\uFF0C\u8096\u5317\u77E5\u9053\u81EA\u5DF1\u7A7F\u8D8A\u4E86\u3002\\n\u8FD8\u7A7F\u8D8A\u5230\u4E86\u4E00\u4E2A\u548C\u524D\u4E16\u76F8\u5DEE\u4E0D\u591A\u7684\u5E73\u884C\u4E16\u754C\u4E2D\u3002\\n\u8FD9\u4E2A\u4E16\u754C\u548C\u524D\u4E16\u84DD\u661F\uFF0C\u6709\u76F8\u4F3C\u7684\u5730\u65B9\uFF0C\u4E5F\u6709\u4E0D\u76F8\u4F3C\u7684\u5730\u65B9\uFF0C\u4F46\u662F\u5927\u4F53\u4E0A\u6765\u8BF4\uFF0C\u5927\u5DEE\u4E0D\u5DEE\uFF01\\n\u60F3\u5FC5\u5F88\u591A\u4EBA\uFF0C\u9762\u5BF9\u7A7F\u8D8A\u90FD\u662F\u590D\u6742\u548C\u6FC0\u52A8\u7684\u611F\u89C9\u3002\\n\u53EF\u662F\uFF0C\u8096\u5317\u5374\u4E0D\u540C\uFF0C\u4ED6\u4E0D\u60F3\u7A7F\u8D8A\u554A\uFF01\\n\u524D\u4E16\u7684\u4ED6\uFF0C\u597D\u6B79\u662F\u4E00\u4E2A\u8EAB\u5BB6\u4EBF\u4E07\u7684\u5BCC\u8C6A\uFF0C\u4E8B\u4E1A\u6709\u6210\uFF0C\u59A5\u59A5\u7684\u9AD8\u5BCC\u5E05\u3002\\n\u4F46\u662F\u8FD9\u4E2A\u4E16\u754C\u4E2D\uFF0C\u8096\u5317\u7684\u8EAB\u4EFD\uFF0C\u786E\u5B9E\u6709\u70B9\u4E00\u8A00\u96BE\u5C3D\uFF01\\n\u56E0\u4E3A\u8FD9\u4E2A\u4E16\u754C\u7684\u8096\u5317\uFF0C\u662F\u4E00\u4E2A\u5B64\u513F\uFF01\\n\u6B64\u523B\uFF0C\u8096\u5317\u5185\u5FC3\u5C31\u4E00\u53E5\u8BDD\uFF1A\u6211\u70ED\u70C8\u7684\u9A6C\uFF0C\u5982\u679C\u6211\u6709\u7F6A\uFF0C\u8BF7\u8BA9\u6CD5\u5F8B\u6765\u5236\u88C1\u6211\uFF0C\u800C\u4E0D\u662F\u8FD9\u6837\u7F9E\u8FB1\u6211\uFF01\\n\u4EFB\u8C01\u524D\u4E16\u662F\u4E00\u4E2A\u4EBF\u4E07\u5BCC\u8C6A\uFF0C\u90FD\u4E0D\u60F3\u7A7F\u8D8A\u5427\uFF1F\u6BD4\u8D77\u524D\u4E16\uFF0C\u8FD9\u4E2A\u4E16\u754C\u7684\u8EAB\u4EFD\u548C\u786C\u4EF6\uFF0C\u5C5E\u5B9E\u6709\u70B9\u2026\u2026\\n\u5B64\u513F\u5C31\u4E0D\u8BF4\u4E86\uFF0C\u8FD8\u957F\u7684\u4E00\u822C\u3002\\n\u6BEB\u65E0\u7279\u8272\uFF0C\u653E\u5728\u4EBA\u7FA4\u4E2D\uFF0C\u5C31\u662F\u5927\u4F17\u8138\u3002\\n\u6BD4\u8D77\u4E11\u7537\uFF0C\u4ED6\u662F\u5E05\u54E5\uFF0C\u6BD4\u8D77\u5E05\u54E5\uFF0C\u4ED6\u662F\u4E00\u822C\u4EBA\uFF01\\n\u53EF\u8C13\u662F\uFF0C\u8FD9\u4E2A\u7A7F\u8D8A\uFF0C\u6781\u5176\u7684\u4E0D\u5BF9\u7B49\uFF01\\n\u5C31\u50CF\u662F\u2026\u2026\u55EF\u2026\u2026\u6276\u8D2B\uFF1F\\n\u3010\u53EE\uFF01\u795E\u8C6A\u8FD4\u5229\u7CFB\u7EDF\u6B63\u5F0F\u5F00\u542F\uFF01\u3011\\n\u5C31\u5728\u8096\u5317\u5410\u69FD\u4E0A\u5929\u4E0D\u516C\uFF0C\u62B1\u6028\u8BA9\u81EA\u5DF1\u7A7F\u8D8A\u7684\u65F6\u5019\uFF0C\u4E00\u9053\u6E05\u8106\u7684\u58F0\u97F3\uFF0C\u51FA\u73B0\u5728\u4E86\u8096\u5317\u7684\u8111\u6D77\u4E2D\u3002\\n\u7CFB\u7EDF\uFF01\uFF1F\\n\u8096\u5317\u5446\u6EDE\u534A\u664C\uFF0C\u53CD\u590D\u786E\u8BA4\u5E76\u975E\u5E7B\u89C9\uFF0C\u8138\u8272\u6162\u6162\u6DA8\u7EA2\u3002\\n\u5C31\u5728\u8FD9\u4E2A\u65F6\u5019\uFF0C\u8096\u5317\u7684\u773C\u524D\u51FA\u73B0\u4E86\u4E00\u4E2A\u5C5E\u6027\u9762\u677F\uFF01\\n\u3010\u795E\u8C6A\u8FD4\u5229\u7CFB\u7EDF\uFF1A\u6D88\u8D39\u5C31\u8FD4\u5229\uFF0C\u968F\u673A\u8FD4\u5229\uFF0C\u6BCF\u6D88\u8D39\u4E00\u7B14\uFF0C\u968F\u673A\u4ECE1-100\u500D\u500D\u6570\u4E2D\u62BD\u53D6\u8FD4\u5229\u500D\u6570\uFF0C\u8FDB\u884C\u8FD4\u5229\uFF01\u3011\\n\u3010\u8FD4\u5229\u8D44\u91D1\u6765\u6E90\u5B89\u5168\u53EF\u9760\uFF0C\u53EF\u751F\u6210\u76F8\u5E94\u7684\u7092\u80A1\u8BB0\u5F55\uFF0C\u65B9\u4FBF\u5BBF\u4E3B\u5411\u5468\u56F4\u4EBA\u89E3\u91CA\uFF01\u3011\\n\u3010\u795E\u8C6A\u5546\u57CE\uFF1A\u5F00\u542F\u3011\\n\uFF08\u6CE8\uFF1A\u6D88\u8D39\u91D1\u989D\uFF0C1:1\u8F6C\u6362\u4E3A\u795E\u8C6A\u70B9\uFF0C\u795E\u8C6A\u70B9\u7528\u4E8E\u795E\u8C6A\u5546\u573A\u7CFB\u7EDF\u8D27\u5E01\uFF09\u8096\u5317\u5FAE\u5FAE\u4E00\u6123\uFF0C\u968F\u5373\u5C06\u76EE\u5149\u5BF9\u51C6\u4E86\u795E\u8C6A\u5546\u57CE\u3002\\n\u4FBF\u770B\u5230\u4E86\u5C5E\u6027\u9762\u677F\u4E0A\uFF0C\u795E\u8C6A\u5546\u57CE\u7684\u9762\u677F\u5207\u6362\u4E86\u4E0B\uFF0C\u53D8\u6210\u4E86\u53EA\u6709\u4E24\u4E2A\u5206\u7C7B\u7684\u5B50\u9762\u677F\u3002\\n\u4E24\u4E2A\u5206\u7C7B\u5206\u522B\u662F\uFF1A\u3010\u6280\u80FD\u3011\u3001\u3010\u60C5\u62A5\u3011\uFF01\\n\u3010\u6280\u80FD\u3011\uFF1A\u5982\u3010\u82F1\u8BED\u7CBE\u901A\u3011\u3001\u3010\u683C\u6597\u7CBE\u901A\u3011\u3001\u3010\u5546\u4E1A\u7CBE\u901A\u3011\u3001\u3010\u989C\u503C+1\u3011\u7B49\u7B49\u5404\u79CD\u5404\u6837\u7684\u6280\u80FD\uFF0C\u5F53\u7136\u4E86\uFF0C\u675C\u7EDD\u4FEE\u4ED9\u8D85\u81EA\u7136\u6280\u80FD\uFF01\\n\u3010\u60C5\u62A5\u3011\uFF1A\u5728\u60C5\u62A5\u5546\u57CE\u4E2D\uFF0C\u53EF\u4EE5\u627E\u5230\u4EFB\u4F55\u60C5\u62A5\uFF0C\u4E0D\u7BA1\u662F\u662F\u4EBA\u6216\u8005\u662F\u7269\uFF0C\u6700\u6050\u6016\u7684\u65F6\u5019\uFF0C\u4E0D\u4EC5\u4EC5\u53EF\u4EE5\u67E5\u5230\u5386\u53F2\u7684\u60C5\u62A5\uFF0C\\n\u8FD8\u80FD\u8D2D\u4E70\u73B0\u5728\u7684\u60C5\u62A5\u4EE5\u53CA\u672A\u6765\u7684\u60C5\u62A5\u3002\\n\u8096\u5317\u5728\u770B\u5B8C\u7CFB\u7EDF\u7684\u4ECB\u7ECD\u540E\uFF0C\u987F\u65F6\u6123\u4F4F\u4E86\u3002\\n\u5174\u594B\u597D\u534A\u5929\uFF0C\u8096\u5317\u63A5\u53D7\u4E86\u8FD9\u4EFD\u4ECE\u5929\u800C\u964D\u7684\u5E78\u8FD0\uFF0C\u4E0D\uFF0C\u7A7F\u8D8A\u8005\u81EA\u5E26\u7684\u91D1\u624B\u6307\u3002\\n\u6B64\u523B\u7684\u8096\u5317\uFF0C\u518D\u4E5F\u6CA1\u6709\u4E86\u7A7F\u8D8A\u7684\u540E\u6094\u4E86\u3002\\n\u90FD\u6709\u795E\u8C6A\u7CFB\u7EDF\u4E86\uFF0C\u8FD8\u540E\u6094\u4EC0\u4E48\u5462\uFF1F\\n\u4E14\u5BF9\u4E8E\u73B0\u5728\u7684\u8EAB\u4EFD\uFF0C\u8096\u5317\u66F4\u52A0\u7684\u559C\u6B22\u4E86\u3002\\n\u4E3A\u4EC0\u4E48\uFF1F\\n\u9996\u5148\uFF0C\u81EA\u5DF1\u662F\u5B64\u513F\uFF0C\u4E0D\u7528\u987E\u53CA\u4EC0\u4E48\u7325\u7410\u53D1\u80B2\uFF0C\u76F4\u63A5\u600E\u4E48\u723D\u600E\u4E48\u6765\uFF0C\u7B49\u4E8E\u5C31\u662F\u4E00\u4E2A\u5168\u65B0\u7684\u8EAB\u4EFD\u3002\\n\u5176\u6B21\uFF0C\u73B0\u5728\u5E74\u8F7B\u554A\uFF0C\u867D\u7136\u5E05\u7684\u4E0D\u660E\u663E\uFF0C\u4F46\u662F\uFF0C\u6709\u7CFB\u7EDF\u554A\uFF01\\n\u5E74\u8F7B\u4EE3\u8868\u4EC0\u4E48\uFF1F\u4EE3\u8868\u53EF\u4EE5\u66F4\u6D6A\u4E86\u554A\uFF01\\n\u6700\u540E\uFF0C\u8FD9\u4E2A\u4E16\u754C\u7684\u8096\u5317\u662F\u4E00\u4E2A\u521A\u521A\u9AD8\u4E2D\u6BD5\u4E1A\uFF0C\u51C6\u5907\u524D\u5F80\u5927\u5B66\u62A5\u9053\u7684\u5B66\u9738\u3002\\n\u8003\u5165\u4E86\u6D59\u7701\u552F\u4E00\u7684\u4E00\u6240985,211\u9AD8\u6821\u676D\u57CE\u5927\u5B66\u3002\\n\u8FD9\u53EB\u4EC0\u4E48\u5F00\u5C40\uFF1F\\n\u8FD9\u5C31\u53EB\u738B\u8005\u5F00\u5C40\uFF01\\n\u540C\u65F6\uFF0C\u8096\u5317\u5728\u4E86\u89E3\u7CFB\u7EDF\u529F\u80FD\u540E\uFF0C\u7ACB\u523B\u77E5\u9053\u4E86\u8FD9\u4E2A\u7CFB\u7EDF\u7684\u6050\u6016\u3002\\n\u9996\u5148\uFF0C\u4ED6\u6CA1\u6709\u5C0F\u8BF4\u4E2D\u7684\u795E\u8C6A\u7CFB\u7EDF\u4E00\u6837\uFF0C\u5404\u79CD\u4EFB\u52A1\uFF0C\u5404\u79CD\u5347\u7EA7\u3002\\n\u81EA\u5DF1\u7684\u7CFB\u7EDF\u5C31\u5F88\u7B80\u5355\u3002\\n\u94B1\u8D8A\u82B1\u8D8A\u591A\uFF0C\u82B1\u94B1\u53D8\u795E\u8C6A\u70B9\uFF0C\u795E\u8C6A\u70B9\u5728\u5546\u57CE\u4E2D\u8D2D\u4E70\u76F8\u5173\u7684\u6280\u80FD\uFF0C\u4F18\u79C0\u81EA\u5DF1\uFF0C\u8D2C\u4F4E\u4ED6\u4EBA\u2026\u2026\u989D\u2026\u2026\u5173\u7167\u4ED6\u4EBA\uFF01\\n\u60C5\u62A5\u7CFB\u7EDF\uFF0C\u66F4\u4E3A\u91CD\u8981\u3002\\n\u8EAB\u4E3A\u524D\u4E16\u7684\u4EBF\u4E07\u5BCC\u8C6A\u517C\u516C\u53F8\u603B\u88C1\u3002\\n\u8096\u5317\u592A\u77E5\u9053\u8FD9\u4E2A\u7684\u91CD\u8981\u6027\u4E86\u3002\\n\u751F\u610F\uFF0C\u65E0\u975E\u4E24\u79CD\uFF0C\u8981\u4E48\u5177\u5907\u6838\u5FC3\u7ADE\u4E89\u529B\uFF0C\u8981\u4E48\u5C31\u662F\u4FE1\u606F\u5DEE\uFF01\\n\u90A3\u4E48\u662F\u4E0D\u662F\u53EF\u4EE5\u6839\u636E\u7CFB\u7EDF\u60C5\u62A5\u7684\u529F\u80FD\uFF0C\u6253\u9020\u81EA\u5DF1\u7684\u5546\u4E1A\u5E1D\u56FD\u5462\uFF1F\\n\u4E0D\u8981\u8BF4\u4EC0\u4E48\uFF0C\u6709\u795E\u8C6A\u7CFB\u7EDF\uFF0C\u8FD8\u53BB\u521B\u4E1A\u3002\\n\u90A3\u662F\u56E0\u4E3A\uFF0C\u5F88\u591A\u4EBA\u4E0D\u61C2\uFF0C\u94B1\u56FA\u7136\u91CD\u8981\uFF0C\u4F46\u662F\u6709\u4E9B\u4E0A\u5C42\u8D44\u6E90\uFF0C\u4E0D\u662F\u7528\u94B1\u80FD\u89E3\u51B3\u7684\u3002\\n\u4F60\u53EA\u6709\u94B1\uFF0C\u6CA1\u6709\u6743\u5229\u6216\u8005\u5730\u4F4D\uFF0C\u6709\u4E9B\u4E1C\u897F\u63A5\u89E6\u4E0D\u5230\u7684\u3002\\n\u4ECE\u6765\u4E00\u6B21\u4E86\uFF0C\u5F53\u7136\u8981\u6743\u5229\u548C\u91D1\u94B1\u90FD\u6293\u4F4F\u3002\\n\u73B0\u5728\u7684\u8096\u5317\uFF0C\u5DF2\u7ECF\u60F3\u5230\u4E86\u4E00\u5957\u672A\u6765\u7684\u53D1\u5C55\u6A21\u5F0F\u4E86\u3002\\n\u4EE5\u7CFB\u7EDF\u8FD4\u5229\u4E3A\u57FA\u7840\uFF0C\u4EE5\u6280\u80FD\u4E3A\u8F85\u52A9\uFF0C\u4EE5\u60C5\u62A5\u4E3A\u6838\u5FC3\uFF0C\u6253\u9020\u81EA\u5DF1\u7684\u5546\u4E1A\u5E1D\u56FD\u3002\\n\u6BD5\u7ADF\uFF0C\u6709\u94B1\u6709\u5730\u4F4D\uFF0C\u5C0F\u59D0\u59D0\u624D\u7231\uFF01\\n\u8FD9\u4E2A\u7CFB\u7EDF\u5F88\u597D\uFF0C\u4E0D\u50CF\u67D0\u4E9B\u7CFB\u7EDF\uFF0C\u8981\u4E48\u4EFB\u52A1\u591A\uFF0C\u8981\u4E48\u76F4\u63A5\u7ED9\u94B1\uFF0C\u6210\u4E3A\u66B4\u53D1\u6237\u3002\\n\u8096\u5317\u8868\u793A\uFF0C\u81EA\u5DF1\u7684\u7CFB\u7EDF\uFF0C\u624D\u662FYYDS\uFF01\\n\u4E3A\u4EC0\u4E48\uFF1F\\n\u56E0\u4E3A\u8FD9\u4E2A\u7CFB\u7EDF\u80FD\u7ED9\u81EA\u5DF1\u63D0\u4F9B\u81EA\u4E3B\u80FD\u52A8\u6027\uFF0C\u8981\u53D8\u5F97\u66F4\u52A0\u7684\u4F18\u79C0\uFF0C\u90A3\u5C31\u82B1\u94B1\u5427\uFF01\\n\u6C2A\u91D1\u53D8\u5F3A\uFF01\\n\u54EA\u6015\u73B0\u5728\u7684\u8096\u5317\u5DF2\u7ECF\u662F30\u591A\u5C81\u7684\u5FC3\u6001\u4E86\uFF0C\u6B64\u523B\u4E5F\u4E0D\u7531\u5F97\u6FC0\u52A8\u4E86\u8D77\u6765\u3002\\n\u53D8\u5E74\u8F7B\u4E86\uFF0C\u8FD8\u6709\u795E\u8C6A\u7CFB\u7EDF\uFF0C\u90A3\u662F\u4E00\u79CD\u4EC0\u4E48\u611F\u89C9\uFF1F\u6B64\u523B\u7684\u8096\u5317\u60F3\u5230\u4E86\u4E00\u53E5\u8BDD\uFF0C\u90A3\u5C31\u662F\u3010\u963F\u5BBE\u6B63\u8F6C\u3011\u4E2D\u8BF4\u7684\u4E00\u53E5\u8BDD\uFF01\\n\u4EBA\u751F\u5C31\u50CF\u559D\u725B\u5976\u76F2\u76D2\uFF0C\u4E0D\u559D\u5230\uFF0C\u4F60\u6C38\u8FDC\u4E0D\u77E5\u9053\u4F60\u4ECA\u5929\u559D\u7684\u662F\u5927\u53F7\u7684\u6930\u6C41\u8FD8\u662F\u5C0F\u53F7\u7684\u65FA\u4ED4\u3002\\n\u4E0D\u8FC7\u8096\u5317\u5012\u662F\u5F88\u786E\u5B9A\uFF1A\u4ECE\u6B64\u4EE5\u540E\uFF0C\u4ED6\u7684\u4EBA\u751F\u4E2D\uFF0C\u6C38\u8FDC\u90FD\u662F\u5976\u5473\uFF01\\n\u4EC0\u4E48\u5927\u53F7\u7684\u6930\u6C41\u5C0F\u53F7\u7684\u65FA\u4ED4\uFF1F\\n\u60F3\u559D\u5927\u7684\u5C31\u548C\u559D\u5927\u7684\uFF0C\u60F3\u559D\u5C0F\u7684\u5C31\u559D\u5C0F\u7684\uFF0C\u5B9E\u5728\u4E0D\u884C\uFF0C\u90A3\u5C31\u559D\u5927\u5C0F\u53F7\u7684\u725B\u5976\uFF01\\n\u4E0D\u8981\u95EE\u4E3A\u4EC0\u4E48\uFF01\\n\u56E0\u4E3A\u963F\u5BBE\u54E5\u8BF4\u7684\u8BDD\uFF0C\u5C31\u662F\u771F\u7406\uFF0C\u4F60\u8981\u6000\u7591\uFF1F\u53BB\u627E\u963F\u5BBE\u54E5\uFF01","owner":"dada","upvotes":3,"downvotes":3,"upvoteDifference":0,"updatedAt":"2026-04-20T02:46:30.155Z"}')}}]);